gVY(){return"\u0905\u092a\u0928\u0947 \u092e\u0941\u0916\u094d\u092f \u092a\u0947\u0936\u0947 \u0914\u0930 \u0935\u093f\u0936\u0947\u0937\u091c\u094d\u091e\u0924\u093e \u0915\u094b \u090f\u0915 \u091b\u094b\u091f\u0947 \u0935\u093e\u0915\u094d\u092f \u092e\u0947\u0902 \u0932\u093f\u0916\u0947\u0902, \u091c\u0948\u0938\u0947 \u201c\u091f\u094b\u0930\u0902\u091f\u094b \u092e\u0947\u0902 \u0906\u0935\u093e\u0938\u0940\u092f \u092a\u094d\u0932\u0902\u092c\u0930\u201d\u0964"},
gVK(){return"\u0905\u092a\u0928\u093e \u092a\u0930\u093f\u091a\u092f \u0926\u0947\u0902 \u0914\u0930 \u092c\u0924\u093e\u090f\u0901 \u0915\u093f \u0906\u092a \u0915\u0948\u0938\u0947 \u0915\u093e\u092e \u0915\u0930\u0924\u0947 \u0939\u0948\u0902, \u0906\u092a\u0915\u0947 \u0932\u093f\u090f \u0915\u094d\u092f\u093e \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0939\u0948 \u0914\u0930 \u0917\u094d\u0930\u093e\u0939\u0915 \u0906\u092a\u0938\u0947 \u0915\u094d\u092f\u093e \u0905\u092a\u0947\u0915\u094d\u0937\u093e \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"},
gW6(){return"\u0905\u092a\u0928\u0940 \u0938\u0947\u0935\u093e\u0913\u0902 \u0914\u0930 \u0915\u093e\u092e \u0915\u0947 \u092a\u094d\u0930\u0915\u093e\u0930\u094b\u0902 \u0915\u0940 \u0938\u0942\u091a\u0940 \u0926\u0947\u0902\u0964 \u0905\u092a\u0928\u0940 \u0935\u093f\u0936\u0947\u0937\u091c\u094d\u091e\u0924\u093e, \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u090f \u091c\u093e\u0928\u0947 \u0935\u093e\u0932\u0947 \u0909\u092a\u0915\u0930\u0923 \u0914\u0930 \u091c\u093f\u0928 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u092e\u0947\u0902 \u0906\u092a \u0935\u093f\u0936\u0947\u0937 \u0930\u0942\u092a \u0938\u0947 \u0915\u0941\u0936\u0932 \u0939\u0948\u0902, \u0909\u0928\u0915\u093e \u0909\u0932\u094d\u0932\u0947\u0916 \u0915\u0930\u0947\u0902\u0964"},
gVW(){return"\u092c\u0924\u093e\u090f\u0901 \u0915\u093f \u0907\u0938 \u0915\u094d\u0937\u0947\u0924\u094d\u0930 \u092e\u0947\u0902 \u0906\u092a\u0915\u093e \u0915\u093f\u0924\u0928\u093e \u0905\u0928\u0941\u092d\u0935 \u0939\u0948, \u0906\u092a\u0915\u0940 \u092d\u0942\u092e\u093f\u0915\u093e\u090f\u0901 \u0915\u094d\u092f\u093e \u0930\u0939\u0940 \u0939\u0948\u0902 \u0914\u0930 \u0906\u092a\u0928\u0947 \u0915\u093f\u0928 \u0938\u0902\u092c\u0902\u0927\u093f\u0924 \u092a\u0930\u093f\u092f\u094b\u091c\u0928\u093e\u0913\u0902 \u092a\u0930 \u0915\u093e\u092e \u0915\u093f\u092f\u093e \u0939\u0948\u0964 \u0905\u092a\u0928\u0947 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u0914\u0930 \u092a\u0930\u093f\u0923\u093e\u092e\u094b\u0902 \u0915\u093e \u0909\u0932\u094d\u0932\u0947\u0916 \u0915\u0930\u0947\u0902\u0964"},
gVT(){return"\u0938\u0902\u092c\u0902\u0927\u093f\u0924 \u0935\u094d\u092f\u093e\u0935\u0938\u093e\u092f\u093f\u0915 \u092f\u093e \u0909\u091a\u094d\u091a \u0936\u093f\u0915\u094d\u0937\u093e \u0915\u093e \u0935\u093f\u0935\u0930\u0923 \u0926\u0947\u0902: \u0938\u0902\u0938\u094d\u0925\u093e\u0928, \u092a\u093e\u0920\u094d\u092f\u0915\u094d\u0930\u092e \u092f\u093e \u0935\u093f\u0937\u092f, \u092f\u094b\u0917\u094d\u092f\u0924\u093e \u0914\u0930 \u092a\u0942\u0930\u093e \u0915\u0930\u0928\u0947 \u0915\u093e \u0935\u0930\u094d\u0937\u0964 \u0928\u0940\u091a\u0947 \u0921\u093f\u092a\u094d\u0932\u094b\u092e\u093e \u0938\u0902\u0932\u0917\u094d\u0928 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"},
gVP(){return"\u0905\u092a\u0928\u0940 \u0938\u0947\u0935\u093e\u0913\u0902 \u0938\u0947 \u0938\u0902\u092c\u0902\u0927\u093f\u0924 \u092a\u093e\u0920\u094d\u092f\u0915\u094d\u0930\u092e, \u0915\u093e\u0930\u094d\u092f\u0936\u093e\u0932\u093e\u090f\u0901 \u0914\u0930 \u0906\u0917\u0947 \u0915\u0940 \u0936\u093f\u0915\u094d\u0937\u093e \u092c\u0924\u093e\u090f\u0901\u0964 \u092a\u094d\u0930\u0926\u093e\u0924\u093e, \u0935\u093f\u0937\u092f, \u092a\u0942\u0930\u093e \u0915\u0930\u0928\u0947 \u0915\u093e \u0935\u0930\u094d\u0937 \u0914\u0930 \u0938\u0940\u0916\u0947 \u0917\u090f \u0915\u094c\u0936\u0932 \u0932\u093f\u0916\u0947\u0902\u0964"},
gVN(){return"\u0905\u092a\u0928\u0947 \u092a\u0947\u0936\u0947\u0935\u0930 \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930, \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0914\u0930 \u092e\u093e\u0928\u094d\u092f\u0924\u093e\u090f\u0901 \u092c\u0924\u093e\u090f\u0901\u0964 \u091c\u093e\u0930\u0940 \u0915\u0930\u0928\u0947 \u0935\u093e\u0932\u0940 \u0938\u0902\u0938\u094d\u0925\u093e, \u091c\u093e\u0930\u0940 \u0939\u094b\u0928\u0947 \u0915\u0940 \u0924\u093e\u0930\u0940\u0916 \u0914\u0930 \u0932\u093e\u0917\u0942 \u0939\u094b\u0928\u0947 \u092a\u0930 \u0938\u092e\u093e\u092a\u094d\u0924\u093f \u0915\u0940 \u0924\u093e\u0930\u0940\u0916 \u0932\u093f\u0916\u0947\u0902; \u092a\u094d\u0930\u092e\u093e\u0923 \u0928\u0940\u091a\u0947 \u0938\u0902\u0932\u0917\u094d\u0928 \u0915\u0930\u0947\u0902\u0964"},
gW4(){return"\u0935\u0947 \u0936\u0939\u0930, \u0907\u0932\u093e\u0915\u0947 \u092f\u093e \u0915\u094d\u0937\u0947\u0924\u094d\u0930 \u092c\u0924\u093e\u090f\u0901 \u091c\u0939\u093e\u0901 \u0906\u092a \u0938\u0947\u0935\u093e \u0926\u0947\u0924\u0947 \u0939\u0948\u0902 \u0914\u0930 \u0915\u093f\u0924\u0928\u0940 \u0926\u0942\u0930 \u0924\u0915 \u091c\u093e\u0928\u0947 \u0915\u094b \u0924\u0948\u092f\u093e\u0930 \u0939\u0948\u0902\u0964 \u092f\u0939 \u092d\u0940 \u092c\u0924\u093e\u090f\u0901 \u0915\u093f \u0915\u094d\u092f\u093e \u0906\u092a \u0926\u0942\u0930\u0938\u094d\u0925 \u0938\u0947\u0935\u093e\u090f\u0901 \u0926\u0947\u0924\u0947 \u0939\u0948\u0902\u0964"},
