gUf(){return"\u0412\u0435\u0440\u043d\u0443\u0442\u044c \u0432 \u0438\u0441\u0442\u043e\u0440\u0438\u044e"},
gTF(){return"\u0417\u0430\u043a\u0430\u0437 \u0441\u043a\u0440\u044b\u0442 \u0438\u0437 \u0438\u0441\u0442\u043e\u0440\u0438\u0438."},
gUe(){return"\u0417\u0430\u043a\u0430\u0437 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0435\u043d \u0432 \u0438\u0441\u0442\u043e\u0440\u0438\u044e."},
gTE(){return"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u0432\u0438\u0434\u0438\u043c\u043e\u0441\u0442\u044c \u0437\u0430\u043a\u0430\u0437\u0430 \u0432 \u0438\u0441\u0442\u043e\u0440\u0438\u0438. \u041f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u0435 \u043f\u043e\u043f\u044b\u0442\u043a\u0443."},
gTJ(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e"},
gTK(){return"\u041e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u0443\u0431\u0440\u0430\u0442\u044c \u0438\u0437 \u0432\u0430\u0448\u0435\u0439 \u0438\u0441\u0442\u043e\u0440\u0438\u0438 \u044d\u0442\u043e\u0442 \u0437\u0430\u043a\u0430\u0437, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0431\u044b\u043b \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u043c?"},
gTM(){return"\u0417\u0430\u043a\u0430\u0437 \u0443\u0434\u0430\u043b\u0435\u043d \u0438\u0437 \u0432\u0430\u0448\u0435\u0439 \u0438\u0441\u0442\u043e\u0440\u0438\u0438."},
gTL(){return"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0443\u0434\u0430\u043b\u0438\u0442\u044c \u0437\u0430\u043a\u0430\u0437 \u0438\u0437 \u0432\u0430\u0448\u0435\u0439 \u0438\u0441\u0442\u043e\u0440\u0438\u0438. \u041f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u0435 \u043f\u043e\u043f\u044b\u0442\u043a\u0443."},
gEw(){return"\u0423\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043d\u044b\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f"},
gEv(){return"\u042d\u0442\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u043f\u043e \u0446\u0435\u043d\u0435, \u0441\u0440\u043e\u043a\u0430\u043c, \u0438\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044e \u0438 \u043e\u0431\u044a\u0435\u043c\u0443 \u0440\u0430\u0431\u043e\u0442 \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u044b \u0434\u043b\u044f \u044d\u0442\u043e\u0433\u043e \u0437\u0430\u043a\u0430\u0437\u0430."},
