gVw(){return"\u042f\u0437\u044b\u043a\u0438 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0443\u043a\u0430\u0437\u0430\u043d\u044b."},
gVy(){return"\u041f\u043e\u0438\u0441\u043a \u043f\u043e \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u044e \u0438\u043b\u0438 \u043a\u043e\u0434\u0443 \u044f\u0437\u044b\u043a\u0430"},
gVx(){return"\u041f\u043e\u0434\u0445\u043e\u0434\u044f\u0449\u0438\u0435 \u044f\u0437\u044b\u043a\u0438 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u044b"},
gVn(){return"\u041a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0438 \u0441\u0430\u043c\u043e\u0433\u043e \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u0430"},
gVo(){return"\u041a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0438 \u0441\u0430\u043c\u043e\u0433\u043e \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0441\u0442\u0430"},
gVr(){return"\u041a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0438 \u043e \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u0435"},
gVd(){return"\u041a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0438 \u043e \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0441\u0442\u0435"},
gV6(){return"\u0412\u0441\u0435"},
gV9(){return"\u0423\u0441\u043f\u0435\u0448\u043d\u044b\u0435"},
gV7(){return"\u041e\u0442\u043c\u0435\u043d\u0435\u043d\u043d\u044b\u0435"},
gV8(){return"\u0416\u0430\u043b\u043e\u0431\u044b"},
gVu(){return"\u042f\u0437\u044b\u043a\u0438"},
gVt(){return"\u0412\u043b\u0430\u0434\u0435\u043d\u0438\u0435 \u044f\u0437\u044b\u043a\u0430\u043c\u0438"},
gVE(){return"\u0420\u043e\u0434\u043d\u043e\u0439 \u044f\u0437\u044b\u043a"},
gVa(){return"\u0418\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0439 \u044f\u0437\u044b\u043a"},
gUX(){return"\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0440\u043e\u0434\u043d\u043e\u0439"},
