gGb(){return"\u0414\u0456\u0430\u043b\u043e\u0433 \u0441\u043a\u0430\u0440\u0433\u0438"},
FZ(a){return"\u0421\u043a\u0430\u0440\u0433\u0430: \xab"+a+"\xbb"},
