gFO(){return"\u041e\u043f\u0438\u0448\u0456\u0442\u044c \u0444\u0430\u043a\u0442\u0438, \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u0456 \u043d\u0430\u0441\u043b\u0456\u0434\u043a\u0438 \u0442\u0430 \u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u0438\u0439 \u043d\u0430\u0441\u0442\u0443\u043f\u043d\u0438\u0439 \u043a\u0440\u043e\u043a, \u0449\u043e \u0434\u043e\u043f\u043e\u043c\u043e\u0436\u0435 \u0437\u043c\u0435\u043d\u0448\u0438\u0442\u0438 \u0432\u0442\u0440\u0430\u0442\u0438. \u041f\u0438\u0448\u0456\u0442\u044c \u0448\u0430\u043d\u043e\u0431\u043b\u0438\u0432\u043e \u0439 \u043f\u043e \u0441\u0443\u0442\u0456."},
